find_rule:
js:
var d = [];
var html = getResCode();
function item(it){
  return {
    title: pdfh(it, 'a&&title') || pdfh(it, 'h3&&Text') || pdfh(it, '.thumb-txt&&Text'),
    desc: pdfh(it, '.public-list-prb&&Text') || pdfh(it, '.public-list-subtitle&&Text'),
    img: pd(it, 'img&&data-src') || pd(it, 'img&&src'),
    url: pd(it, 'a&&href')
  };
}
pdfa(html, '.public-list-box').forEach(function (it) {
  var o = item(it);
  o.col_type = 'movie_3_marquee';
  if (o.url.indexOf('/movie/') > -1) d.push(o);
});
setResult(d);

searchFind:
js:
var d = [];
var html = getResCode();
if (html.indexOf('Just a moment') > -1 || html.indexOf('public-list') < 0) {
  html = fetchCodeByWebView(MY_URL, {
    checkJs: "document.querySelector('.public-list-box,.search-box') ? 'ok' : ''"
  });
}
function item(it){
  return {
    title: pdfh(it, 'a&&title') || pdfh(it, 'h3&&Text') || pdfh(it, '.thumb-txt&&Text'),
    desc: pdfh(it, '.public-list-prb&&Text') || pdfh(it, '.public-list-subtitle&&Text'),
    img: pd(it, 'img&&data-src') || pd(it, 'img&&src'),
    url: pd(it, 'a&&href')
  };
}
var list = pdfa(html, '.public-list-box');
if (list.length == 0) list = pdfa(html, '.search-box');
list.forEach(function (it) {
  var o = item(it);
  if (o.url.indexOf('/movie/') > -1) d.push(o);
});
setResult(d);

detail_find_rule:
js:
var d = [];
var html = getResCode();
var id = MY_URL.match(/movie\/(\d+)/)[1];
d.push({
  title: pdfh(html, '.slide-info-title&&Text'),
  desc: pdfh(html, '#height_limit&&Text'),
  img: pd(html, '.detail-pic&&img&&data-src'),
  url: MY_URL,
  col_type: 'movie_1_vertical_pic_blur'
});
var tabs = pdfa(html, '.anthology-tab&&a');
var boxes = pdfa(html, '.anthology-list-box');
boxes.forEach(function (box, i) {
  var name = tabs[i] ? pdfh(tabs[i], 'Text').replace(/\d+$/, '').trim() : '线路' + (i + 1);
  d.push({ title: '““' + name + '””', url: 'hiker://empty', col_type: 'text_center_1' });
  pdfa(box, 'ul&&li').forEach(function (li) {
    var href = pdfh(li, 'a&&href');
    var sid = pdfh(li, 'a&&data-play-sid') || (i + 1);
    var nid = href.split('-').pop();
    d.push({
      title: pdfh(li, 'a&&Text'),
      url: 'https://huarw.com/play/' + id + '-' + sid + '-' + nid + $('').lazyRule(function () {
        var h = fetch(input, { headers: { 'User-Agent': MOBILE_UA } });
        var m = h.match(/player_aaaa\s*=\s*(\{[\s\S]*?\})\s*<\/script>/);
        if (m) {
          var j = JSON.parse(m[1]);
          var u = j.url;
          if (j.encrypt == 1) u = unescape(u);
          else if (j.encrypt == 2) u = unescape(base64Decode(u));
          if (/\.(m3u8|mp4)/.test(u)) return u;
        }
        return 'video://' + input;
      }),
      col_type: 'text_4'
    });
  });
});
setResult(d);
